function updateFirebaseStatus(online) {
    const statusEl = document.getElementById('firebaseStatus');
    if (statusEl) {
        statusEl.textContent = online ? '🟢 متصل' : '🔴 غير متصل';
        statusEl.style.color = online ? 'var(--success)' : 'var(--secondary)';
    }
    const connStatus = document.getElementById('connectionStatus');
    if (connStatus) {
        connStatus.className = `connection-status ${online ? 'online' : 'offline'}`;
        document.getElementById('connectionText').textContent = online ? 'متصل' : 'غير متصل';
    }
}

// ============================================================
// دالة مساعدة للحصول على TIMESTAMP
// ============================================================
function getRealtimeTimestamp() {
    if (rtdb && rtdb.ServerValue && rtdb.ServerValue.TIMESTAMP) {
        return rtdb.ServerValue.TIMESTAMP;
    }
    // ✅ البديل: استخدام وقت الخادم المحلي
    return Date.now();
}

// ============================================================
// Realtime Service - نسخة محسنة
// ============================================================
const RealtimeService = {
    _refs: {},
    _isReady: false,

    checkReady() {
        if (!rtdb) {
            console.warn('⚠️ Realtime Database not ready, attempting re-init...');
            try {
                if (typeof firebase !== 'undefined' && firebase.database) {
                    rtdb = firebase.database();
                    console.log('✅ Realtime Database re-initialized');
                }
            } catch (e) {
                console.error('❌ Failed to re-initialize Realtime Database:', e);
            }
        }
        return !!rtdb;
    },

    getRef(path) {
        if (!this.checkReady()) {
            throw new Error('Realtime Database not initialized');
        }
        if (!this._refs[path]) {
            this._refs[path] = rtdb.ref(path);
        }
        return this._refs[path];
    },

    // ✅ دالة جديدة لجلب بيانات مرة واحدة
    async getOnce(path) {
        const ref = this.getRef(path);
        const snapshot = await ref.once('value');
        return snapshot.val();
    },

    async add(path, data) {
        const ref = this.getRef(path);
        const newRef = ref.push();
        const timestamp = getRealtimeTimestamp();
        await newRef.set({
            ...data,
            createdAt: timestamp
        });
        return { id: newRef.key, ...data };
    },

    async update(path, id, data) {
        await this.getRef(path).child(id).update(data);
        return { id, ...data };
    },

    async delete(path, id) {
        await this.getRef(path).child(id).remove();
    },

    async getAll(path) {
        const snapshot = await this.getRef(path).once('value');
        const data = snapshot.val();
        if (!data) return [];
        return Object.keys(data).map(key => ({ id: key, ...data[key] }));
    },

    listen(path, callback) {
        const ref = this.getRef(path);
        const listener = ref.on('value', (snapshot) => {
            const data = snapshot.val();
            if (!data) {
                callback(null);
                return;
            }
            if (typeof data === 'object' && !Array.isArray(data) && data !== null) {
                const results = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                callback(results);
            } else {
                callback(data);
            }
        });
        return () => ref.off('value', listener);
    },

    listenDoc(path, callback) {
        const ref = this.getRef(path);
        const listener = ref.on('value', (snapshot) => {
            const data = snapshot.val();
            if (!data) {
                callback(null);
                return;
            }
            callback(data);
        });
        return () => ref.off('value', listener);
    },

    getRawRef(path) {
        if (!this.checkReady()) {
            throw new Error('Realtime Database not initialized');
        }
        return rtdb.ref(path);
    }
};
