// 6. مدير البيانات (DataManager)
// ============================================================
const DataManager = {
data: {
    questions: [],
    leaderboard: [],
    rooms: [],
    storeItems: [],
    transactions: []
},
    _listeners: [],
    _unsubscribers: [],
    _isLoading: false,
    _lastUpdate: null,

async loadAll() {
    if (this._isLoading) return this.data;
    this._isLoading = true;
    try {
        // التحقق من الاتصال أولاً
        const isOnline = await checkInternetConnection();
        if (!isOnline) {
            console.warn('⚠️ غير متصل بالإنترنت، استخدام البيانات المخزنة');
            this._lastUpdate = new Date();
            this._notifyListeners();
            showToast('⚠️ غير متصل، يتم عرض البيانات المخزنة مؤقتاً', 'info', 3000);
            this._isLoading = false;
            return this.data;
        }
        
        const collections = ['questions', 'leaderboard', 'rooms', 'storeItems', 'transactions'];
        
        // محاولة جلب البيانات مع مهلة
        const results = await Promise.race([
            Promise.all(collections.map(col => FirestoreService.getAll(col))),
            new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 10000))
        ]);
        
        collections.forEach((col, idx) => {
            this.data[col] = results[idx];
        });
        this._lastUpdate = new Date();
        this._notifyListeners();
        return this.data;
    } catch (e) {
        console.error('❌ Error loading data:', e);
        // إذا كان الخطأ بسبب الاتصال، استخدم البيانات المخزنة
        if (e.message === 'timeout' || e.message.includes('unavailable')) {
            showToast('⚠️ بطء في الاتصال، استخدام البيانات المخزنة مؤقتاً', 'info', 4000);
        } else {
            showToast('⚠️ خطأ في تحميل البيانات، جاري استخدام البيانات المخزنة', 'error');
        }
        this._lastUpdate = new Date();
        this._notifyListeners();
        return this.data;
    } finally {
        this._isLoading = false;
    }
},

startListening() {
    if (!isFirebaseReady) return;
    this._unsubscribers.forEach(unsub => unsub());
    this._unsubscribers = [];
    const collections = [
        { name: 'questions', key: 'questions' },
        { name: 'leaderboard', key: 'leaderboard' },
        { name: 'rooms', key: 'rooms' },
        { name: 'storeItems', key: 'storeItems' },
        { name: 'transactions', key: 'transactions' }
    ];
    collections.forEach(({ name, key }) => {
        // ✅ استخدام listen الجديد بدون orderBy
        const unsub = FirestoreService.listen(name, (data) => {
            this.data[key] = data;
            this._lastUpdate = new Date();
            this._notifyListeners();
        });
        this._unsubscribers.push(unsub);
    });
},

    addListener(callback) {
        this._listeners.push(callback);
        callback(this.data);
        return () => {
            this._listeners = this._listeners.filter(cb => cb !== callback);
        };
    },

    _notifyListeners() {
        this._listeners.forEach(cb => {
            try { cb(this.data); } catch (e) { console.warn('Listener error:', e); }
        });
    },

    async add(collection, item) {
        const result = await FirestoreService.add(collection, item);
        return result;
    },

    async update(collection, id, item) {
        return await FirestoreService.update(collection, id, item);
    },

    async delete(collection, id) {
        await FirestoreService.delete(collection, id);
    },

getStats() {
    return {
        questions: this.data.questions.length,
        leaderboard: this.data.leaderboard.length,
        rooms: this.data.rooms.length,
        storeItems: this.data.storeItems.length
    };
},
};

