App._refreshMultiplayerGames = async function() {
    const container = document.getElementById('multiplayerGamesList');
    if (!container) return;

    try {
        const snapshot = await db.collection('multiplayerGames')
            .where('status', '==', 'waiting')
            .get();

        const games = [];
        snapshot.forEach(doc => {
            games.push({ id: doc.id, ...doc.data() });
        });

        if (games.length === 0) {
            container.innerHTML = '<div class="text-gray">لا توجد مباريات نشطة حالياً</div>';
            return;
        }

        let html = '<div class="games-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:1rem;">';
        games.forEach(g => {
            html += `
                <div class="card" style="padding:1rem;">
                    <div style="display:flex;justify-content:space-between;align-items:center;">
                        <span style="font-weight:700;">${g.hostName || 'مجهول'}</span>
                        <span class="badge badge-success">🟢 مفتوحة</span>
                    </div>
                    <div style="font-size:0.85rem;color:var(--gray);">
                        <span>👥 ${g.players ? g.players.length : 0} لاعب</span>
                        <span>• ${g.settings?.questionCount || 10} سؤال</span>
                        <span>• رمز: <strong>${g.code}</strong></span>
                    </div>
                    <button class="btn btn-sm btn-primary mt-1" onclick="App._joinMultiplayerGame('${g.id}')">
                        <i class="fas fa-sign-in-alt"></i> انضمام
                    </button>
                </div>
            `;
        });
        html += '</div>';
        container.innerHTML = html;
    } catch (e) {
        console.error('Error loading games:', e);
        container.innerHTML = '<div class="text-gray">⚠️ خطأ في تحميل المباريات</div>';
    }
};

App._joinMultiplayerGame = async function(gameId) {
    const password = prompt('أدخل كلمة المرور (إن وجدت):');
    if (password === null) return;
    await MultiplayerManager.joinGame(gameId, password);
};

App._setupMultiplayerHandlers = function() {
    const form = document.getElementById('createMultiplayerForm');
    if (form) {
        form.addEventListener('submit', async (e) => {
            e.preventDefault();
            const settings = {
                difficulty: document.getElementById('mpDifficulty').value,
                category: document.getElementById('mpCategory').value,
                questionType: document.getElementById('mpQuestionType').value,
                questionCount: document.getElementById('mpQuestionCount').value,
                timeLimit: document.getElementById('mpTimeLimit').value,
                password: document.getElementById('mpPassword').value.trim() || null
            };
            const gameId = await MultiplayerManager.createGame(settings);
            if (gameId) {
                form.reset();
            }
        });
    }

    const joinBtn = document.getElementById('mpJoinBtn');
    if (joinBtn) {
        joinBtn.addEventListener('click', async () => {
            const code = document.getElementById('mpJoinCode').value.trim().toUpperCase();
            const password = document.getElementById('mpJoinPassword').value.trim();
            if (!code) {
                showToast('يرجى إدخال رمز المباراة', 'error');
                return;
            }
            try {
                const snapshot = await db.collection('multiplayerGames')
                    .where('code', '==', code)
                    .where('status', '==', 'waiting')
                    .get();
                if (snapshot.empty) {
                    showToast('لا توجد مباراة بهذا الرمز', 'error');
                    return;
                }
                const doc = snapshot.docs[0];
                await MultiplayerManager.joinGame(doc.id, password);
            } catch (e) {
                showToast('❌ خطأ: ' + e.message, 'error');
            }
        });
    }
};

App._showMultiplayerGamePage = function() {
    const section = document.getElementById('section-multiplayer-game');
    if (section) {
        section.style.display = 'block';
        section.style.position = 'fixed';
        section.style.top = '0';
        section.style.left = '0';
        section.style.right = '0';
        section.style.bottom = '0';
        section.style.zIndex = '1050';
        section.style.background = 'var(--dark)';
        section.style.overflowY = 'auto';
        section.style.padding = '1rem';
    }
    
    // ===== إظهار زر العودة في صفحة اللعب الجماعي =====
    const backBtn = document.querySelector('#section-multiplayer-game .back-to-home');
    if (backBtn) backBtn.style.display = 'inline-flex';
    
    // إخفاء الأقسام الأخرى
    document.querySelectorAll('.section').forEach(s => {
        if (s.id !== 'section-multiplayer-game' && s.id !== 'section-multiplayer-result') {
            s.style.display = 'none';
        }
    });
};

App._hideMultiplayerGamePage = function() {
    const section = document.getElementById('section-multiplayer-game');
    if (section) {
        section.style.display = 'none';
    }
    // إظهار الأقسام الأخرى مرة أخرى
    document.querySelectorAll('.section').forEach(s => {
        if (s.id !== 'section-multiplayer-game' && s.id !== 'section-multiplayer-result') {
            s.style.display = '';
        }
    });
    // إعادة تفعيل القسم الحالي
    if (this.currentSection) {
        const activeSection = document.getElementById(`section-${this.currentSection}`);
        if (activeSection) activeSection.style.display = 'block';
    }
};

App._showMultiplayerResultPage = function(gameId) {
    const section = document.getElementById('section-multiplayer-result');
    if (section) {
        section.style.display = 'block';
        section.style.position = 'fixed';
        section.style.top = '0';
        section.style.left = '0';
        section.style.right = '0';
        section.style.bottom = '0';
        section.style.zIndex = '1050';
        section.style.background = 'var(--dark)';
        section.style.overflowY = 'auto';
        section.style.padding = '1rem';
    }
    // إخفاء صفحات اللعب
    const gameSection = document.getElementById('section-multiplayer-game');
    if (gameSection) gameSection.style.display = 'none';
    // عرض النتائج
    App._renderMultiplayerResult(gameId);
};

App._hideMultiplayerResultPage = function() {
    const section = document.getElementById('section-multiplayer-result');
    if (section) {
        section.style.display = 'none';
    }
    // إظهار الأقسام الأخرى
    document.querySelectorAll('.section').forEach(s => {
        if (s.id !== 'section-multiplayer-game' && s.id !== 'section-multiplayer-result') {
            s.style.display = '';
        }
    });
};

// ===== عرض شاشة الانتظار (Lobby) =====
App._renderMultiplayerLobby = function(gameId) {
    const container = document.getElementById('multiplayerGameContainer');
    if (!container) return;

    db.collection('multiplayerGames').doc(gameId).get().then((doc) => {
        if (!doc.exists) {
            container.innerHTML = '<div class="text-gray">المباراة غير موجودة</div>';
            return;
        }
        const g = doc.data();
        const isHost = g.hostId === AuthService.currentUser?.uid;
        const players = g.players || [];

        let html = `
            <div class="card">
                <div class="card-title">
                    <i class="fas fa-users"></i> غرفة الانتظار
                    <span class="badge badge-primary">رمز: ${g.code}</span>
                    ${g.password ? '<span class="badge badge-warning">🔒 محمية</span>' : ''}
                </div>
                <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:0.5rem;margin-bottom:0.5rem;">
                    <span>المضيف: <strong>${g.hostName}</strong></span>
                    <span>اللاعبين: ${players.length}</span>
                    <span>الحالة: <span class="badge badge-warning">⏳ في انتظار اللاعبين</span></span>
                </div>
                <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:0.5rem;">
                    ${players.map(p => `
                        <div style="background:var(--glass);padding:0.5rem;border-radius:10px;text-align:center;">
                            <div style="font-size:1.5rem;">👤</div>
                            <div style="font-weight:600;font-size:0.85rem;">${p.name}</div>
                            ${p.uid === AuthService.currentUser?.uid ? '<div style="font-size:0.6rem;color:var(--accent);">(أنت)</div>' : ''}
                            ${p.uid === g.hostId ? '<div style="font-size:0.6rem;color:var(--success);">👑 مضيف</div>' : ''}
                        </div>
                    `).join('')}
                </div>
                <div style="margin-top:1rem;display:flex;gap:0.5rem;flex-wrap:wrap;">
                    ${isHost ? `
                        <button class="btn btn-success" id="mpStartGameBtn" ${players.length < 2 ? 'disabled' : ''}>
                            <i class="fas fa-play"></i> بدء المباراة
                        </button>
                        <button class="btn btn-danger" id="mpDeleteGameBtn">
                            <i class="fas fa-trash"></i> حذف المباراة
                        </button>
                    ` : `
                        <button class="btn btn-danger" id="mpLeaveLobbyBtn">
                            <i class="fas fa-sign-out-alt"></i> مغادرة
                        </button>
                    `}
                </div>
            </div>
        `;
        container.innerHTML = html;

        if (isHost) {
            const startBtn = document.getElementById('mpStartGameBtn');
            if (startBtn) {
                startBtn.addEventListener('click', () => {
                    MultiplayerManager.startGame(gameId);
                });
            }
            const deleteBtn = document.getElementById('mpDeleteGameBtn');
            if (deleteBtn) {
                deleteBtn.addEventListener('click', async () => {
                    if (confirm('هل أنت متأكد من حذف المباراة؟')) {
                        await db.collection('multiplayerGames').doc(gameId).delete();
                        showToast('تم حذف المباراة', 'info');
                        MultiplayerManager.leaveGame();
                    }
                });
            }
        }
        const leaveBtn = document.getElementById('mpLeaveLobbyBtn');
        if (leaveBtn) {
            leaveBtn.addEventListener('click', () => {
                MultiplayerManager.leaveGame();
            });
        }

        if (MultiplayerManager.unsubscribeGame) {
            MultiplayerManager.unsubscribeGame();
        }
        MultiplayerManager.unsubscribeGame = db.collection('multiplayerGames').doc(gameId)
            .onSnapshot((snap) => {
                if (!snap.exists) {
                    container.innerHTML = '<div class="text-gray">تم حذف المباراة</div>';
                    return;
                }
                const updated = snap.data();
                if (updated.status === 'playing') {
                    App._showMultiplayerGamePage();
                    App._renderMultiplayerGame(gameId);
                } else if (updated.status === 'finished') {
                    App._showMultiplayerResultPage(gameId);
                } else {
                    App._renderMultiplayerLobby(gameId);
                }
            });
    });
};

App._renderMultiplayerGame = function(gameId) {
    const container = document.getElementById('multiplayerGameContent');
    if (!container) {
        console.warn('⚠️ multiplayerGameContent not found');
        return;
    }

    // التحقق من وجود المباراة
    db.collection('multiplayerGames').doc(gameId).get().then((doc) => {
        if (!doc.exists) {
            container.innerHTML = '<div class="text-gray">المباراة غير موجودة</div>';
            return;
        }
        const g = doc.data();
        if (g.status !== 'playing') {
            container.innerHTML = '<div class="text-gray">المباراة ليست في حالة لعب</div>';
            return;
        }

        const currentQ = g.currentQuestion || 0;
        const questions = g.questions || [];
        if (currentQ >= questions.length) {
            MultiplayerManager.endGame(gameId);
            return;
        }
        const question = questions[currentQ];
        const players = g.players || [];
        const answers = g.answers || {};
        const user = AuthService.currentUser;
        const totalPlayers = players.length;
        const answeredCount = Object.keys(answers).length;

        const timeLimit = g.settings?.timeLimit || 15;
        const elapsed = (Date.now() - g.questionStartTime) / 1000;
        const timeLeft = Math.max(0, timeLimit - Math.floor(elapsed));
        const progress = Math.min((elapsed / timeLimit) * 100, 100);

        // ============================================================
        // استخراج النقاط والإحصائيات من scores
        // ============================================================
        const scoresData = g.scores || {};
        const playersWithScores = players.map(p => {
            const stats = scoresData[p.uid] || {};
            return {
                ...p,
                // نقاط المباراة
                score: stats.score || 0,
                correct: stats.correct || 0,
                wrong: stats.wrong || 0,
                streak: stats.streak || 0,
                bestStreak: stats.bestStreak || 0,
                totalTime: stats.totalTime || 0,
                avgTime: stats.avgTime || 0,
                answersCount: stats.answersCount || 0,
                answeredQuestions: stats.answeredQuestions || [],
                // النقاط المتكاملة
                levelPoints: stats.levelPoints || 0,
                coins: stats.coins || 0,
                totalScore: stats.totalScore || stats.score || 0
            };
        });

        // ============================================================
        // الترتيب حسب النقاط الكلية (totalScore)
        // ============================================================
        const sorted = [...playersWithScores].sort((a, b) => (b.totalScore || 0) - (a.totalScore || 0));

        // ============================================================
        // التحقق من إجابة المستخدم الحالي
        // ============================================================
        const userAnswered = user && answers[user.uid] && answers[user.uid][currentQ] !== undefined;
        if (userAnswered) {
            if (MultiplayerManager._timerInterval) {
                clearInterval(MultiplayerManager._timerInterval);
                MultiplayerManager._timerInterval = null;
            }
        }

        if (!MultiplayerManager._timerInterval && !userAnswered) {
            MultiplayerManager._startTimer(gameId);
        }

        // ============================================================
        // بناء خيارات السؤال حسب النوع
        // ============================================================
        let optionsHtml = '';
        const qType = question.type || 'multiple_choice';

        if (qType === 'multiple_choice' || qType === 'true_false') {
            const opts = question.options || [];
            optionsHtml = opts.map((opt, idx) => {
                const isSelected = userAnswered && answers[user.uid][currentQ].answer === idx;
                const isCorrect = isSelected && answers[user.uid][currentQ].isCorrect;
                const isWrong = isSelected && !isCorrect;
                let btnClass = 'option-btn';
                if (userAnswered) {
                    btnClass += ' disabled';
                    if (idx === question.correct) btnClass += ' show-correct';
                    if (isWrong) btnClass += ' selected-wrong';
                }
                return `<button class="${btnClass}" onclick="App._submitMultiplayerAnswer(${idx})" ${userAnswered ? 'disabled' : ''}>
                    ${String.fromCharCode(65 + idx)}. ${opt}
                </button>`;
            }).join('');
        } else if (qType === 'fill_blank') {
            optionsHtml = `
                <div style="display:flex;gap:0.5rem;justify-content:center;max-width:400px;margin:0 auto;">
                    <input type="text" id="mpFillBlankInput" placeholder="اكتب الإجابة..." 
                           style="flex:1;padding:8px 12px;border-radius:8px;border:1px solid var(--glass-border);background:var(--glass);color:var(--light);" 
                           ${userAnswered ? 'disabled' : ''}>
                    <button class="btn btn-primary" onclick="App._submitMultiplayerFillBlank()" ${userAnswered ? 'disabled' : ''}>
                        تأكيد
                    </button>
                </div>
            `;
        } else if (qType === 'matching') {
            const pairs = question.matchingPairs || [];
            if (userAnswered) {
                const userMatch = answers[user.uid][currentQ].answer || {};
                let resultHtml = pairs.map(pair => {
                    const isMatch = userMatch[pair.left] === pair.right;
                    return `<div style="display:flex;justify-content:center;gap:1rem;padding:0.2rem;">
                        <span>${pair.left} ↔ </span>
                        <span style="color:${isMatch ? 'var(--success)' : 'var(--secondary)'};">${userMatch[pair.left] || '(لم يختر)'}</span>
                        ${!isMatch ? `<span style="color:var(--gray);font-size:0.8rem;">(الصحيح: ${pair.right})</span>` : ''}
                    </div>`;
                }).join('');
                optionsHtml = `<div>${resultHtml}</div>`;
            } else {
                const rightOptions = pairs.map(p => p.right);
                let selectsHtml = pairs.map((pair, idx) => `
                    <div style="display:flex;align-items:center;gap:0.5rem;justify-content:center;margin-bottom:0.3rem;">
                        <span>${pair.left} ↔ </span>
                        <select id="mpMatchSelect_${idx}" style="padding:4px 8px;border-radius:6px;background:var(--glass);border:1px solid var(--glass-border);color:var(--light);">
                            <option value="">--- اختر ---</option>
                            ${rightOptions.map(r => `<option value="${r}">${r}</option>`).join('')}
                        </select>
                    </div>
                `).join('');
                optionsHtml = `
                    <div>${selectsHtml}</div>
                    <button class="btn btn-primary mt-1" onclick="App._submitMultiplayerMatching()">تأكيد المطابقة</button>
                `;
            }
        } else if (qType === 'ordering') {
            const items = question.orderedItems || [];
            if (userAnswered) {
                const userOrder = answers[user.uid][currentQ].answer || [];
                const isCorrect = JSON.stringify(userOrder) === JSON.stringify(items);
                let resultHtml = userOrder.map((item, idx) => `
                    <div style="display:flex;gap:0.5rem;justify-content:center;padding:0.2rem;">
                        <span>${idx+1}</span>
                        <span style="color:${isCorrect ? 'var(--success)' : 'var(--gray)'};">${item}</span>
                        ${!isCorrect ? `<span style="color:var(--secondary);font-size:0.8rem;">(الصحيح: ${items[idx]})</span>` : ''}
                    </div>
                `).join('');
                optionsHtml = `<div>${resultHtml}</div>`;
            } else {
                const orderKey = `mpOrder_${gameId}`;
                if (!window[orderKey]) {
                    window[orderKey] = shuffleArray([...items]);
                }
                const currentOrder = window[orderKey];
                let orderHtml = currentOrder.map((item, idx) => `
                    <div style="display:flex;align-items:center;gap:0.5rem;justify-content:center;margin:0.2rem 0;">
                        <span style="min-width:30px;">${idx+1}</span>
                        <span>${item}</span>
                        <button class="btn btn-xs btn-outline" onclick="App._moveOrderingItem(${idx}, -1, '${gameId}')">▲</button>
                        <button class="btn btn-xs btn-outline" onclick="App._moveOrderingItem(${idx}, 1, '${gameId}')">▼</button>
                    </div>
                `).join('');
                optionsHtml = `
                    <div>${orderHtml}</div>
                    <button class="btn btn-primary mt-1" onclick="App._submitMultiplayerOrdering('${gameId}')">تأكيد الترتيب</button>
                `;
            }
        } else {
            optionsHtml = `<div class="text-gray">نوع السؤال غير مدعوم</div>`;
        }

        // ============================================================
        // بناء واجهة اللعب
        // ============================================================
        let html = `
            <div class="game-container">
                <!-- رأس اللعبة -->
                <div class="game-header">
                    <div style="display:flex;align-items:center;gap:0.8rem;flex-wrap:wrap;">
                        <span class="badge badge-primary">${currentQ+1}/${questions.length}</span>
                        <span class="badge ${timeLeft <= 5 ? 'badge-danger' : 'badge-warning'}">⏱ ${timeLeft}s</span>
                        <span class="badge badge-info">👥 ${answeredCount}/${totalPlayers}</span>
                    </div>
                    <button class="btn btn-sm btn-danger" id="mpExitGameBtn">
                        <i class="fas fa-times"></i> خروج
                    </button>
                </div>

                <!-- شريط التقدم -->
                <div class="game-progress" style="margin-bottom:0.8rem;">
                    <div class="progress-bar" style="height:6px;">
                        <div class="fill" style="width:${progress}%;height:100%;background:linear-gradient(90deg, var(--primary), var(--accent));border-radius:10px;transition:width 0.3s ease;"></div>
                    </div>
                </div>

                <!-- مربع السؤال -->
                <div class="question-box">
                    <div class="q-category">📚 ${question.category || 'عام'}</div>
                    <div class="q-type-badge">${GameEngine._getTypeLabel(question.type)}</div>
                    <div class="q-text">${question.question}</div>
                    <div class="options-grid">
                        ${optionsHtml}
                    </div>
                </div>

                <!-- الترتيب الحالي -->
                <div class="card" style="padding:0.8rem;">
                    <div class="card-title" style="font-size:1rem;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0.3rem;">
                        <span><i class="fas fa-crown" style="color:var(--accent);"></i> الترتيب الحالي</span>
                        <span style="font-size:0.7rem;color:var(--gray);">
                            ⭐ النقاط الكلية • ✅ الصحيح • ❌ الخاطئ
                        </span>
                    </div>
                    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:0.3rem;">
                        ${sorted.map((p, i) => {
                            const isMe = p.uid === user?.uid;
                            const medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `${i+1}.`;
                            const isTop = i < 3;
                            const pTotal = (p.totalScore || p.score || 0);
                            const pCorrect = p.correct || 0;
                            const pWrong = p.wrong || 0;
                            
                            return `
                                <div class="player-rank-item ${isTop ? 'top' : ''} ${isMe ? 'me' : ''}" 
                                     style="background:${isTop ? 'var(--accent)' : (isMe ? 'var(--primary)' : 'var(--glass)')};
                                            ${isTop ? 'color:var(--dark);' : ''}
                                            ${isMe && !isTop ? 'color:#fff;' : ''}
                                            padding:0.3rem 0.6rem;border-radius:6px;
                                            display:flex;justify-content:space-between;align-items:center;
                                            border:${isMe ? '2px solid var(--accent)' : '1px solid var(--glass-border)'};
                                            transition:all 0.3s ease;">
                                    <div style="display:flex;align-items:center;gap:0.3rem;min-width:0;">
                                        <span style="font-weight:700;font-size:0.9rem;flex-shrink:0;">${medal}</span>
                                        <span style="font-weight:600;font-size:0.85rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100px;">
                                            ${p.name} ${isMe ? '👈' : ''}
                                        </span>
                                        ${p.bestStreak >= 5 ? '<span style="font-size:0.7rem;flex-shrink:0;">🔥</span>' : ''}
                                        ${p.streak >= 3 ? '<span style="font-size:0.6rem;flex-shrink:0;">⚡</span>' : ''}
                                    </div>
                                    <div style="display:flex;align-items:center;gap:0.5rem;flex-shrink:0;">
                                        <span style="font-weight:700;font-size:0.9rem;color:${isTop ? 'var(--dark)' : 'var(--accent)'};">⭐ ${pTotal}</span>
                                        <span style="font-size:0.6rem;color:${isTop ? 'rgba(0,0,0,0.5)' : 'var(--gray)'};display:flex;gap:0.2rem;">
                                            <span style="color:var(--success);">✅${pCorrect}</span>
                                            <span style="color:var(--secondary);">❌${pWrong}</span>
                                        </span>
                                    </div>
                                </div>
                            `;
                        }).join('')}
                    </div>
                    
                    <!-- إحصائيات سريعة -->
                    <div style="display:flex;flex-wrap:wrap;gap:0.5rem 1rem;margin-top:0.5rem;padding-top:0.5rem;border-top:1px solid var(--glass-border);font-size:0.7rem;color:var(--gray);">
                        <span>🎯 متوسط الدقة: 
                            <strong style="color:var(--light);">
                                ${sorted.length > 0 ? Math.round(sorted.reduce((sum, p) => {
                                    const acc = p.answersCount > 0 ? (p.correct / p.answersCount) * 100 : 0;
                                    return sum + acc;
                                }, 0) / sorted.length) : 0}%
                            </strong>
                        </span>
                        <span>🔥 أفضل سلسلة: 
                            <strong style="color:var(--accent);">
                                ${Math.max(...sorted.map(p => p.bestStreak || 0))}
                            </strong>
                        </span>
                        <span>⚡ متوسط السرعة: 
                            <strong style="color:var(--info);">
                                ${sorted.length > 0 ? (sorted.reduce((sum, p) => sum + (p.avgTime || 0), 0) / sorted.length).toFixed(1) : 0}s
                            </strong>
                        </span>
                        <span>📊 إجمالي الإجابات: 
                            <strong style="color:var(--primary);">
                                ${sorted.reduce((sum, p) => sum + (p.answersCount || 0), 0)}
                            </strong>
                        </span>
                    </div>
                </div>
            </div>
        `;

        container.innerHTML = html;

        // ============================================================
        // ربط أزرار الخروج
        // ============================================================
        const exitBtn = document.getElementById('mpExitGameBtn');
        if (exitBtn) {
            exitBtn.onclick = function() {
                if (confirm('هل تريد مغادرة المباراة؟')) {
                    MultiplayerManager.leaveGame();
                }
            };
        }

    }).catch(error => {
        console.error('❌ Error rendering multiplayer game:', error);
        container.innerHTML = `
            <div class="card" style="text-align:center;padding:2rem;color:var(--secondary);">
                <i class="fas fa-exclamation-circle" style="font-size:3rem;"></i>
                <h3>حدث خطأ في تحميل واجهة اللعب</h3>
                <p class="text-gray">${error.message}</p>
                <button class="btn btn-primary mt-1" onclick="MultiplayerManager.leaveGame();">
                    <i class="fas fa-home"></i> العودة
                </button>
            </div>
        `;
    });
};

// ===== إرسال إجابة (اختيار من متعدد / صح خطأ) =====
App._submitMultiplayerAnswer = async function(answerIndex) {
    const gameId = MultiplayerManager.currentGameId;
    if (!gameId) {
        showToast('لا توجد مباراة نشطة', 'error');
        return;
    }
    // منع الإجابة المكررة
    const user = AuthService.currentUser;
    if (!user) {
        showToast('يجب تسجيل الدخول', 'error');
        return;
    }
    // التحقق من أن المستخدم لم يجب بالفعل
    const doc = await db.collection('multiplayerGames').doc(gameId).get();
    if (doc.exists) {
        const game = doc.data();
        const answers = game.answers || {};
        const currentQ = game.currentQuestion;
        if (answers[user.uid] && answers[user.uid][currentQ] !== undefined) {
            showToast('لقد أجبت بالفعل على هذا السؤال', 'info');
            return;
        }
    }
    MultiplayerManager.submitAnswer(gameId, answerIndex);
};

// ===== إرسال إجابة (ملء الفراغ) =====
App._submitMultiplayerFillBlank = async function() {
    const input = document.getElementById('mpFillBlankInput');
    if (!input) return;
    const answer = input.value.trim();
    if (!answer) {
        showToast('يرجى كتابة الإجابة', 'info');
        return;
    }
    const gameId = MultiplayerManager.currentGameId;
    if (!gameId) return;
    
    // التحقق من عدم الإجابة المكررة
    const user = AuthService.currentUser;
    if (!user) return;
    const doc = await db.collection('multiplayerGames').doc(gameId).get();
    if (doc.exists) {
        const game = doc.data();
        const answers = game.answers || {};
        const currentQ = game.currentQuestion;
        if (answers[user.uid] && answers[user.uid][currentQ] !== undefined) {
            showToast('لقد أجبت بالفعل على هذا السؤال', 'info');
            return;
        }
    }
    MultiplayerManager.submitAnswer(gameId, answer);
};

// ===== إرسال إجابة (مطابقة) =====
App._submitMultiplayerMatching = async function() {
    const gameId = MultiplayerManager.currentGameId;
    if (!gameId) return;
    
    // التحقق من عدم الإجابة المكررة
    const user = AuthService.currentUser;
    if (!user) return;
    const doc = await db.collection('multiplayerGames').doc(gameId).get();
    if (doc.exists) {
        const game = doc.data();
        const answers = game.answers || {};
        const currentQ = game.currentQuestion;
        if (answers[user.uid] && answers[user.uid][currentQ] !== undefined) {
            showToast('لقد أجبت بالفعل على هذا السؤال', 'info');
            return;
        }
    }
    
    const selects = document.querySelectorAll('[id^="mpMatchSelect_"]');
    const result = {};
    selects.forEach(select => {
        const container = select.closest('div');
        const leftSpan = container ? container.querySelector('span') : null;
        if (leftSpan) {
            const left = leftSpan.textContent.trim();
            result[left] = select.value;
        }
    });
    const allSelected = Object.values(result).every(v => v !== '');
    if (!allSelected) {
        showToast('يرجى اختيار جميع المطابقات', 'info');
        return;
    }
    MultiplayerManager.submitAnswer(gameId, result);
};

// ===== تحريك عنصر الترتيب =====
App._moveOrderingItem = function(index, direction, gameId) {
    const orderKey = `mpOrder_${gameId}`;
    if (!window[orderKey]) return;
    const arr = window[orderKey];
    const newIndex = index + direction;
    if (newIndex < 0 || newIndex >= arr.length) return;
    [arr[index], arr[newIndex]] = [arr[newIndex], arr[index]];
    App._renderMultiplayerGame(gameId);
};

// ===== إرسال إجابة (ترتيب) =====
App._submitMultiplayerOrdering = async function(gameId) {
    const orderKey = `mpOrder_${gameId}`;
    if (!window[orderKey]) return;
    
    // التحقق من عدم الإجابة المكررة
    const user = AuthService.currentUser;
    if (!user) return;
    const doc = await db.collection('multiplayerGames').doc(gameId).get();
    if (doc.exists) {
        const game = doc.data();
        const answers = game.answers || {};
        const currentQ = game.currentQuestion;
        if (answers[user.uid] && answers[user.uid][currentQ] !== undefined) {
            showToast('لقد أجبت بالفعل على هذا السؤال', 'info');
            return;
        }
    }
    
    const order = window[orderKey];
    MultiplayerManager.submitAnswer(gameId, order);
};

App._selectedMatchMode = 'normal_1v1';

App._selectMatchMode = function(mode) {
    const modeNames = {
        'normal_1v1': 'عادي 1 ضد 1',
        'normal_2v2': 'عادي 2 ضد 2',
        'crossword_1v1': 'كلمات متقاطعة 1 ضد 1',
        'crossword_2v2': 'كلمات متقاطعة 2 ضد 2'
    };
    this._selectedMatchMode = mode;
    document.getElementById('selectedModeDisplay').textContent = modeNames[mode] || mode;
    document.querySelectorAll('.mode-option').forEach(btn => {
        btn.classList.remove('btn-primary');
        btn.classList.add('btn-outline');
        if (btn.dataset.mode === mode) {
            btn.classList.remove('btn-outline');
            btn.classList.add('btn-primary');
        }
    });
};

App._startMatchWithCurrentMode = function() {
    this._closeModal('matchSettingsModal');
    MatchmakingSystem.startMatchmaking(this._selectedMatchMode);
};

App._renderMultiplayerResult = function(gameId) {
    const container = document.getElementById('multiplayerResultContent');
    if (!container) {
        console.error('❌ multiplayerResultContent not found');
        return;
    }

    db.collection('multiplayerGames').doc(gameId).get().then(async (doc) => {
        if (!doc.exists) {
            container.innerHTML = '<div class="text-gray">المباراة غير موجودة</div>';
            return;
        }

        const g = doc.data();
        const user = AuthService.currentUser;
        const isLightTheme = document.body.classList.contains('light-theme');

        // ===== 1. استخراج بيانات اللاعبين والإحصائيات =====
        const scoresData = g.scores || {};
        const playersWithStats = g.players.map(p => {
            const stats = scoresData[p.uid] || {};
            return {
                ...p,
                score: stats.score || 0,
                correct: stats.correct || 0,
                wrong: stats.wrong || 0,
                streak: stats.streak || 0,
                bestStreak: stats.bestStreak || 0,
                totalTime: stats.totalTime || 0,
                avgTime: stats.avgTime || 0,
                answersCount: stats.answersCount || 0
            };
        });

        const sorted = [...playersWithStats].sort((a, b) => (b.score || 0) - (a.score || 0));
        const winner = sorted[0];
        const totalQuestions = g.questions ? g.questions.length : 0;

        // ===== 2. حساب المكافآت لكل لاعب =====
        const rewardsMap = {};
        let userRewards = null;
        for (let i = 0; i < sorted.length; i++) {
            const player = sorted[i];
            const rank = i + 1;
            try {
                const rewards = MultiplayerRewards.calculateRewards(player, rank, sorted.length, {
                    totalQuestions: totalQuestions
                });
                rewardsMap[player.uid] = rewards;
                if (player.uid === user?.uid) {
                    userRewards = rewards;
                }
            } catch (e) {
                console.warn('Error calculating rewards for player', player.uid, e);
                rewardsMap[player.uid] = {
                    total: 0,
                    rankPoints: 0,
                    levelPoints: 0,
                    coins: 0,
                    breakdown: { rankPoints: [], levelPoints: [], coins: [] },
                    penalty: false
                };
            }
        }

        // ===== 3. تطبيق المكافآت للمستخدم الحالي وتحديث الملف الشخصي فوراً =====
        if (user && userRewards) {
            await MultiplayerRewards.applyRewards(user.uid, userRewards);
            // تحديث واجهة المستخدم فوراً
            App._updateUserUI(AuthService.currentUser);
            App._updateProfileTabContent(AuthService.currentUser);
            App._updateFollowCounts();
            App._refreshActiveBoosts();
        }

        // ===== 4. حساب تقدم المستوى والرتبة (قبل وبعد المكافآت) =====
        const userData = AuthService.currentUser;
        const oldTotalScore = (userData?.totalScore || 0) - (userRewards?.levelPoints || 0);
        const newTotalScore = userData?.totalScore || 0;
        const oldLevel = getLevel(oldTotalScore);
        const newLevel = getLevel(newTotalScore);
        const oldLevelProgress = getLevelProgress(oldTotalScore);
        const newLevelProgress = getLevelProgress(newTotalScore);

        const oldRankPoints = (userData?.rankPoints || 0) - (userRewards?.rankPoints || 0);
        const newRankPoints = userData?.rankPoints || 0;
        const oldRank = getRank(oldRankPoints);
        const newRank = getRank(newRankPoints);

        const levelUp = newLevel.level > oldLevel.level;
        const rankUp = newRank.name !== oldRank.name && newRankPoints > oldRankPoints;
        const rankDown = newRankPoints < oldRankPoints;

        // ===== 5. دالة عرض الإحصائيات الكاملة (الخطوة النهائية) =====
        const displayFullResults = function() {
            const textColor = isLightTheme ? 'var(--dark)' : 'var(--light)';
            const cardBg = isLightTheme ? 'rgba(255,255,255,0.9)' : 'var(--card-bg)';
            const borderColor = isLightTheme ? 'rgba(0,0,0,0.08)' : 'var(--border-color)';

            let html = `
                <div style="text-align:center;margin-bottom:1.5rem;color:${textColor};">
                    <div style="font-size:4rem;margin-bottom:0.5rem;">🏆</div>
                    <h2 style="font-size:2rem;font-weight:900;color:${textColor};">انتهت المباراة!</h2>
                    <div style="font-size:1.5rem;font-weight:700;color:var(--accent);">
                        الفائز: ${winner.name} (⭐ ${winner.score || 0} نقطة)
                    </div>
                    <div style="font-size:0.9rem;color:var(--gray);margin-top:0.3rem;">
                        ${totalQuestions} سؤال • ${sorted.length} لاعب
                    </div>
                    <div style="display:flex;gap:0.5rem;justify-content:center;flex-wrap:wrap;margin-top:0.5rem;">
                        <button class="btn btn-sm btn-outline" onclick="App._shareMultiplayerResult('${gameId}')">
                            <i class="fas fa-share-alt"></i> مشاركة النتيجة
                        </button>
                        <button class="btn btn-sm btn-primary" onclick="MultiplayerManager.leaveGame();">
                            <i class="fas fa-home"></i> العودة إلى القائمة
                        </button>
                    </div>
                </div>
                <hr style="border-color:var(--glass-border);margin:1rem 0;">
                <h3 style="font-size:1.2rem;margin-bottom:1rem;color:${textColor};"><i class="fas fa-list"></i> الترتيب النهائي والإحصائيات</h3>
            `;

            // عرض كل لاعب مع تفاصيل المكافآت
            sorted.forEach((p, idx) => {
                const isMe = p.uid === user?.uid;
                const rank = idx + 1;
                const rewards = rewardsMap[p.uid] || {
                    total: 0,
                    rankPoints: 0,
                    levelPoints: 0,
                    coins: 0,
                    breakdown: { rankPoints: [], levelPoints: [], coins: [] },
                    penalty: false
                };
                const isWinner = rank === 1;
                const medal = rank === 1 ? '🥇' : rank === 2 ? '🥈' : rank === 3 ? '🥉' : `${rank}.`;

                const answeredCount = p.answersCount || 0;
                const missed = totalQuestions - answeredCount;
                const accuracy = answeredCount > 0 ? Math.round((p.correct / answeredCount) * 100) : 0;
                const avgTime = p.avgTime ? p.avgTime.toFixed(1) : '0';
                const pScore = p.score || 0;
                const pCorrect = p.correct || 0;
                const pWrong = p.wrong || 0;
                const pBestStreak = p.bestStreak || 0;

                // بناء تفاصيل المكافآت
                let rewardsDetailsHtml = '';

                const buildBreakdownList = (items) => {
                    if (!items || items.length === 0) return '';
                    return items.map(item => `
                        <span style="font-size:0.55rem;background:var(--card-bg);padding:0.1rem 0.5rem;border-radius:30px;border:1px solid var(--glass-border);">
                            ${item.label}
                        </span>
                    `).join('');
                };

                if (isMe) {
                    // عرض كامل للمستخدم الحالي
                    rewardsDetailsHtml = `
                        <div style="margin-top:0.5rem;padding:0.5rem;background:var(--glass);border-radius:8px;border:1px solid ${rewards.penalty ? 'var(--secondary)' : 'var(--accent)'};">
                            <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:0.3rem;text-align:center;">
                                <div style="background:${rewards.rankPoints >= 0 ? 'rgba(46,204,113,0.1)' : 'rgba(255,107,107,0.1)'};border-radius:6px;padding:0.3rem;">
                                    <div style="font-size:0.6rem;color:var(--gray);">🏅 نقاط الرتبة</div>
                                    <div style="font-weight:700;font-size:1.1rem;color:${rewards.rankPoints >= 0 ? 'var(--success)' : 'var(--secondary)'};">${rewards.rankPoints >= 0 ? '+' : ''}${rewards.rankPoints}</div>
                                </div>
                                <div style="background:rgba(108,99,255,0.1);border-radius:6px;padding:0.3rem;">
                                    <div style="font-size:0.6rem;color:var(--gray);">⭐ نقاط المستوى</div>
                                    <div style="font-weight:700;font-size:1.1rem;color:var(--primary);">+${rewards.levelPoints}</div>
                                </div>
                                <div style="background:rgba(255,217,61,0.1);border-radius:6px;padding:0.3rem;">
                                    <div style="font-size:0.6rem;color:var(--gray);">🪙 العملات</div>
                                    <div style="font-weight:700;font-size:1.1rem;color:var(--accent);">+${rewards.coins}</div>
                                </div>
                            </div>
                            
                            ${rewards.breakdown?.rankPoints?.length > 0 ? `
                                <div style="margin-top:0.3rem;padding:0.3rem;background:rgba(46,204,113,0.05);border-radius:6px;border-right:2px solid var(--success);">
                                    <div style="font-size:0.6rem;font-weight:700;color:var(--gray);">🏅 تفاصيل نقاط الرتبة:</div>
                                    <div style="display:flex;flex-wrap:wrap;gap:0.2rem;margin-top:0.2rem;">
                                        ${buildBreakdownList(rewards.breakdown.rankPoints)}
                                    </div>
                                </div>
                            ` : ''}
                            
                            ${rewards.breakdown?.levelPoints?.length > 0 ? `
                                <div style="margin-top:0.3rem;padding:0.3rem;background:rgba(108,99,255,0.05);border-radius:6px;border-right:2px solid var(--primary);">
                                    <div style="font-size:0.6rem;font-weight:700;color:var(--gray);">⭐ تفاصيل نقاط المستوى:</div>
                                    <div style="display:flex;flex-wrap:wrap;gap:0.2rem;margin-top:0.2rem;">
                                        ${buildBreakdownList(rewards.breakdown.levelPoints)}
                                    </div>
                                </div>
                            ` : ''}
                            
                            ${rewards.breakdown?.coins?.length > 0 ? `
                                <div style="margin-top:0.3rem;padding:0.3rem;background:rgba(255,217,61,0.05);border-radius:6px;border-right:2px solid var(--accent);">
                                    <div style="font-size:0.6rem;font-weight:700;color:var(--gray);">🪙 تفاصيل العملات:</div>
                                    <div style="display:flex;flex-wrap:wrap;gap:0.2rem;margin-top:0.2rem;">
                                        ${buildBreakdownList(rewards.breakdown.coins)}
                                    </div>
                                </div>
                            ` : ''}

                            <div style="margin-top:0.3rem;display:grid;grid-template-columns:1fr 1fr 1fr;gap:0.2rem;font-size:0.6rem;color:var(--gray);border-top:1px solid var(--glass-border);padding-top:0.3rem;">
                                <div>✅ صحيح: <strong style="color:var(--success);">${pCorrect}</strong></div>
                                <div>❌ خاطئ: <strong style="color:var(--secondary);">${pWrong}</strong></div>
                                <div>🎯 دقة: <strong>${accuracy}%</strong></div>
                                <div>🔥 أفضل سلسلة: <strong style="color:var(--accent);">${pBestStreak}</strong></div>
                                <div>⏱ متوسط الوقت: <strong>${avgTime}s</strong></div>
                                <div>⏳ لم يجب: <strong style="color:${missed > 0 ? 'var(--secondary)' : 'var(--success)'};">${missed}</strong></div>
                            </div>
                        </div>
                    `;
                } else {
                    // عرض مختصر للآخرين مع زر عرض التفاصيل
                    const rankBreakdown = rewards.breakdown?.rankPoints?.map(item => item.label).join(' • ') || '';
                    const levelBreakdown = rewards.breakdown?.levelPoints?.map(item => item.label).join(' • ') || '';
                    const coinBreakdown = rewards.breakdown?.coins?.map(item => item.label).join(' • ') || '';

                    rewardsDetailsHtml = `
                        <button class="btn btn-xs btn-outline" onclick="
                            const container = this.nextElementSibling;
                            const icon = this.querySelector('i');
                            if (container.style.display === 'none') {
                                container.style.display = 'block';
                                icon.className = 'fas fa-chevron-up';
                            } else {
                                container.style.display = 'none';
                                icon.className = 'fas fa-chevron-down';
                            }
                        " style="font-size:0.55rem;padding:2px 8px;margin-top:0.2rem;background:transparent;border:1px solid var(--glass-border);border-radius:30px;color:var(--gray);">
                            <i class="fas fa-chevron-down"></i> عرض المكافآت
                        </button>
                        <div style="display:none;margin-top:0.3rem;padding:0.4rem;background:var(--glass);border-radius:6px;">
                            <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:0.2rem;text-align:center;font-size:0.75rem;">
                                <div>
                                    <div style="font-size:0.5rem;color:var(--gray);">🏅 رتبة</div>
                                    <div style="font-weight:700;color:${rewards.rankPoints >= 0 ? 'var(--success)' : 'var(--secondary)'};">${rewards.rankPoints >= 0 ? '+' : ''}${rewards.rankPoints}</div>
                                </div>
                                <div>
                                    <div style="font-size:0.5rem;color:var(--gray);">⭐ مستوى</div>
                                    <div style="font-weight:700;color:var(--primary);">+${rewards.levelPoints}</div>
                                </div>
                                <div>
                                    <div style="font-size:0.5rem;color:var(--gray);">🪙 عملات</div>
                                    <div style="font-weight:700;color:var(--accent);">+${rewards.coins}</div>
                                </div>
                            </div>
                            ${rankBreakdown ? `<div style="margin-top:0.2rem;font-size:0.55rem;color:var(--gray);border-top:1px solid var(--glass-border);padding-top:0.2rem;"><strong>🏅 رتبة:</strong> ${rankBreakdown}</div>` : ''}
                            ${levelBreakdown ? `<div style="font-size:0.55rem;color:var(--gray);"><strong>⭐ مستوى:</strong> ${levelBreakdown}</div>` : ''}
                            ${coinBreakdown ? `<div style="font-size:0.55rem;color:var(--gray);"><strong>🪙 عملات:</strong> ${coinBreakdown}</div>` : ''}
                            <div style="margin-top:0.2rem;display:grid;grid-template-columns:1fr 1fr;gap:0.1rem;font-size:0.55rem;color:var(--gray);border-top:1px solid var(--glass-border);padding-top:0.2rem;">
                                <div>✅ ${pCorrect} صحيح</div>
                                <div>❌ ${pWrong} خاطئ</div>
                                <div>🎯 ${accuracy}% دقة</div>
                                <div>🔥 ${pBestStreak} أفضل سلسلة</div>
                            </div>
                        </div>
                    `;
                }

                html += `
                    <div style="background:${isWinner ? '#FFD700' : cardBg};padding:0.8rem 1.2rem;border-radius:10px;border:2px solid ${isWinner ? 'var(--accent)' : borderColor};${isWinner ? 'box-shadow: 0 0 40px rgba(255,217,61,0.3);' : ''} ${isMe && !isWinner ? 'border-right:4px solid var(--primary);' : ''} margin-bottom:0.8rem;">
                        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0.5rem;">
                            <div style="display:flex;align-items:center;gap:0.5rem;">
                                <span style="font-weight:700;font-size:1.1rem;color:${isWinner ? 'var(--dark)' : textColor};">${medal}</span>
                                <span style="font-weight:700;font-size:1.1rem;color:${isWinner ? 'var(--dark)' : textColor};">${p.name} ${isMe ? '👈 (أنت)' : ''}</span>
                                ${isWinner ? '<span style="font-size:1.5rem;">👑</span>' : ''}
                                ${rewards.penalty ? '<span style="font-size:1.2rem;color:var(--secondary);">💔</span>' : ''}
                            </div>
                            <div style="display:flex;gap:0.8rem;flex-wrap:wrap;align-items:center;">
                                <span style="font-weight:900;font-size:1.2rem;color:${isWinner ? 'var(--dark)' : 'var(--accent)'};">⭐ ${pScore}</span>
                                <span style="font-size:0.75rem;color:${isWinner ? 'rgba(0,0,0,0.6)' : 'var(--gray)'};">المجموع: ${rewards.total}</span>
                            </div>
                        </div>
                        ${rewardsDetailsHtml}
                    </div>
                `;
            });

            container.innerHTML = html;
        };

        // ===== 6. عرض شريط التقدم المتحرك =====
        const renderProgressStep = (title, icon, oldProgress, newProgress, oldLabel, newLabel, sub, isLast = false, isLevel = true) => {
            const diff = newProgress - oldProgress;
            const isPositive = diff >= 0;
            const isRank = !isLevel;

            // رسالة عند التقدم
            let messageHtml = '';
            if (isLevel && levelUp) {
                messageHtml = `
                    <div style="margin-top:0.8rem;padding:0.6rem;background:rgba(255,217,61,0.15);border-radius:10px;border:1px solid var(--accent);animation: fadeUp 0.5s ease;">
                        <span style="font-size:2rem;">🎉</span>
                        <span style="font-weight:700;color:var(--accent);font-size:1.3rem;">مستوى جديد! ${newLevel.level}</span>
                        <div style="font-size:0.9rem;color:var(--gray);">تهانينا! وصلت إلى المستوى ${newLevel.level}</div>
                    </div>
                `;
            } else if (isRank && rankUp) {
                messageHtml = `
                    <div style="margin-top:0.8rem;padding:0.6rem;background:rgba(255,217,61,0.15);border-radius:10px;border:1px solid var(--accent);animation: fadeUp 0.5s ease;">
                        <span style="font-size:2rem;">👑</span>
                        <span style="font-weight:700;color:var(--accent);font-size:1.3rem;">رتبة جديدة! ${newRank.name}</span>
                        <div style="font-size:0.9rem;color:var(--gray);">رائع! لقد وصلت إلى ${newRank.name}</div>
                    </div>
                `;
            } else if (isRank && rankDown) {
                messageHtml = `
                    <div style="margin-top:0.8rem;padding:0.6rem;background:rgba(255,107,107,0.15);border-radius:10px;border:1px solid var(--secondary);animation: fadeUp 0.5s ease;">
                        <span style="font-size:2rem;">💔</span>
                        <span style="font-weight:700;color:var(--secondary);font-size:1.3rem;">تراجع في الرتبة</span>
                        <div style="font-size:0.9rem;color:var(--gray);">${oldRank.name} → ${newRank.name}</div>
                    </div>
                `;
            }

            return `
                <div class="progress-step" style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:70vh;text-align:center;padding:1rem;">
                    <div style="font-size:3.5rem;margin-bottom:0.5rem;">${icon}</div>
                    <h3 style="font-size:2rem;font-weight:800;margin-bottom:0.3rem;color:var(--light);">${title}</h3>
                    <div style="font-size:0.9rem;color:var(--gray);margin-bottom:0.5rem;">${oldLabel} → ${newLabel}</div>
                    <div style="max-width:450px;width:100%;margin:0 auto;">
                        <div class="progress-bar" style="height:16px;background:var(--glass);border-radius:10px;overflow:hidden;position:relative;">
                            <div class="fill" style="width:${Math.max(0, Math.min(oldProgress, 100))}%;height:100%;background:${isPositive ? 'linear-gradient(90deg, var(--primary), var(--accent))' : 'linear-gradient(90deg, var(--secondary), var(--primary))'};border-radius:10px;transition:width 1.8s cubic-bezier(0.4, 0, 0.2, 1);"></div>
                            <span style="position:absolute;right:10px;top:50%;transform:translateY(-50%);font-size:0.75rem;font-weight:700;color:#fff;text-shadow:0 1px 4px rgba(0,0,0,0.6);" id="progressPercent">${Math.round(oldProgress)}%</span>
                        </div>
                        <div style="display:flex;justify-content:space-between;font-size:0.75rem;color:var(--gray);margin-top:0.2rem;">
                            <span>${oldLabel}</span>
                            <span>${newLabel}</span>
                        </div>
                    </div>
                    <div style="font-size:0.9rem;color:var(--gray);margin-top:0.5rem;">${sub}</div>
                    ${messageHtml}
                    <button class="btn btn-primary mt-2" id="progressNextBtn" style="justify-content:center;min-width:140px;font-size:1rem;padding:12px 30px;">
                        ${isLast ? 'عرض النتائج 🏆' : 'التالي →'}
                    </button>
                </div>
            `;
        };

        // ===== 7. تعريف الخطوات =====
        let currentStep = 0;
        const steps = [
            {
                title: `المستوى ${newLevel.level}`,
                icon: '⭐',
                oldProgress: oldLevelProgress.progress,
                newProgress: newLevelProgress.progress,
                oldLabel: `المستوى ${oldLevel.level}`,
                newLabel: `المستوى ${newLevel.level}`,
                sub: `+${userRewards?.levelPoints || 0} نقطة مستوى`,
                isLevel: true
            },
            {
                title: `الرتبة ${newRank.name}`,
                icon: '🏅',
                oldProgress: oldRank.progress,
                newProgress: newRank.progress,
                oldLabel: oldRank.name,
                newLabel: newRank.name,
                sub: `${userRewards?.rankPoints >= 0 ? '+' : ''}${userRewards?.rankPoints || 0} نقطة رتبة`,
                isLevel: false
            }
        ];

        // ===== 8. عرض الخطوة الأولى =====
        container.innerHTML = `
            <div id="progressStepsContainer" style="display:flex;align-items:center;justify-content:center;min-height:80vh;">
                ${renderProgressStep(
                    steps[0].title,
                    steps[0].icon,
                    steps[0].oldProgress,
                    steps[0].newProgress,
                    steps[0].oldLabel,
                    steps[0].newLabel,
                    steps[0].sub,
                    steps.length === 1,
                    steps[0].isLevel
                )}
            </div>
        `;

        // ===== 9. تحريك شريط التقدم للخطوة الأولى =====
        setTimeout(() => {
            const fill = document.querySelector('.progress-step .fill');
            const percent = document.getElementById('progressPercent');
            if (fill) {
                const start = steps[0].oldProgress;
                const end = steps[0].newProgress;
                let startTime = null;
                const duration = 1800;
                const animate = (time) => {
                    if (!startTime) startTime = time;
                    const elapsed = time - startTime;
                    const progress = Math.min(elapsed / duration, 1);
                    const current = start + (end - start) * progress;
                    fill.style.width = `${Math.max(0, Math.min(current, 100))}%`;
                    if (percent) percent.textContent = `${Math.round(current)}%`;
                    if (progress < 1) {
                        requestAnimationFrame(animate);
                    } else {
                        if (percent) percent.textContent = `${Math.round(end)}%`;
                    }
                };
                requestAnimationFrame(animate);
            }
        }, 300);

        // ===== 10. ربط زر "التالي" للخطوة الأولى =====
        document.getElementById('progressNextBtn')?.addEventListener('click', function() {
            currentStep++;
            if (currentStep >= steps.length) {
                displayFullResults();
                return;
            }
            // عرض الخطوة التالية
            const container = document.getElementById('progressStepsContainer');
            container.innerHTML = `
                <div style="display:flex;align-items:center;justify-content:center;min-height:80vh;">
                    ${renderProgressStep(
                        steps[currentStep].title,
                        steps[currentStep].icon,
                        steps[currentStep].oldProgress,
                        steps[currentStep].newProgress,
                        steps[currentStep].oldLabel,
                        steps[currentStep].newLabel,
                        steps[currentStep].sub,
                        currentStep === steps.length - 1,
                        steps[currentStep].isLevel
                    )}
                </div>
            `;
            // تحريك الشريط
            setTimeout(() => {
                const fill = document.querySelector('.progress-step .fill');
                const percent = document.getElementById('progressPercent');
                if (fill) {
                    const start = steps[currentStep].oldProgress;
                    const end = steps[currentStep].newProgress;
                    let startTime = null;
                    const duration = 1800;
                    const animate = (time) => {
                        if (!startTime) startTime = time;
                        const elapsed = time - startTime;
                        const progress = Math.min(elapsed / duration, 1);
                        const current = start + (end - start) * progress;
                        fill.style.width = `${Math.max(0, Math.min(current, 100))}%`;
                        if (percent) percent.textContent = `${Math.round(current)}%`;
                        if (progress < 1) {
                            requestAnimationFrame(animate);
                        } else {
                            if (percent) percent.textContent = `${Math.round(end)}%`;
                        }
                    };
                    requestAnimationFrame(animate);
                }
            }, 300);
            // ربط زر "التالي" الجديد
            document.getElementById('progressNextBtn')?.addEventListener('click', function() {
                currentStep++;
                if (currentStep >= steps.length) {
                    displayFullResults();
                }
            });
        });

    }).catch(error => {
        console.error('❌ Error rendering multiplayer result:', error);
        const container = document.getElementById('multiplayerResultContent');
        if (container) {
            container.innerHTML = `
                <div class="card" style="text-align:center;padding:2rem;color:var(--secondary);">
                    <i class="fas fa-exclamation-circle" style="font-size:3rem;"></i>
                    <h3>حدث خطأ في عرض النتائج</h3>
                    <p class="text-gray">${error.message}</p>
                    <button class="btn btn-primary mt-1" onclick="MultiplayerManager.leaveGame();">
                        <i class="fas fa-home"></i> العودة
                    </button>
                </div>
            `;
        }
    });
};

App._shareMultiplayerResult = function(gameId) {
    db.collection('multiplayerGames').doc(gameId).get().then((doc) => {
        if (!doc.exists) return;
        const g = doc.data();
        const sorted = [...g.players].sort((a, b) => (b.score || 0) - (a.score || 0));
        const winner = sorted[0];
        const text = `🏆 نتائج المباراة الجماعية!\n👑 الفائز: ${winner.name} (${winner.score} نقطة)\n📊 الترتيب:\n${sorted.map((p, i) => `${i+1}. ${p.name} - ${p.score} نقطة (✅${p.correct||0} ❌${p.wrong||0})`).join('\n')}`;
        if (navigator.share) {
            navigator.share({ title: 'نتيجة المباراة', text }).catch(() => {});
        } else {
            navigator.clipboard.writeText(text).then(() => {
                showToast('✅ تم نسخ النتيجة', 'success');
            }).catch(() => {
                showToast('⚠️ لا يمكن النسخ', 'error');
            });
        }
    });
};

// ============================================================
// عرض الإحصائيات المتقدمة في صفحة التحليلات
// ============================================================
// ============================================================
// تحديث الإحصائيات يدوياً
// ============================================================

App._refreshStats = function() {
    const user = AuthService.currentUser;
    if (!user) {
        showToast('⚠️ يجب تسجيل الدخول أولاً', 'error');
        return;
    }

    showToast('⏳ جاري تحديث الإحصائيات...', 'info', 2000);
    
    // إعادة تحميل بيانات المستخدم من Firestore
    db.collection('users').doc(user.uid).get().then(doc => {
        if (doc.exists) {
            const data = doc.data();
            // تحديث بيانات المستخدم الحالي
            Object.assign(user, data);
            AuthService._notifyListeners();
            
            // إعادة عرض قسم التحليلات
            const section = document.getElementById('section-analytics');
            if (section) {
                section.innerHTML = App._renderAnalyticsSection();
            }
            
            showToast('✅ تم تحديث الإحصائيات بنجاح', 'success', 3000);
        } else {
            showToast('❌ لم يتم العثور على بيانات المستخدم', 'error');
        }
    }).catch(err => {
        console.error('Error refreshing stats:', err);
        showToast('❌ خطأ في تحديث الإحصائيات: ' + err.message, 'error');
    });
};

// ============================================================
// تصدير الدوال العامة
// ============================================================

// التأكد من أن App._refreshStats معرفة
if (typeof App !== 'undefined' && App) {
    App._refreshStats = App._refreshStats || function() {
        console.warn('⚠️ _refreshStats called but not fully implemented');
        showToast('⚠️ جاري تحديث الإحصائيات...', 'info');
        const user = AuthService.currentUser;
        if (user) {
            db.collection('users').doc(user.uid).get().then(doc => {
                if (doc.exists) {
                    const data = doc.data();
                    Object.assign(user, data);
                    AuthService._notifyListeners();
                    const section = document.getElementById('section-analytics');
                    if (section) {
                        section.innerHTML = App._renderAnalyticsSection();
                    }
                    showToast('✅ تم تحديث الإحصائيات', 'success');
                }
            }).catch(() => {});
        }
    };
}

// ============================================================
// نظام الرتبة للعبة الجماعية
// ============================================================

function getRank(rankPoints) {
    const points = typeof rankPoints === 'number' ? rankPoints : 0;
    let currentRank = RANKS[0];
    for (const rank of RANKS) {
        if (points >= rank.min) {
            currentRank = rank;
        }
    }
    const currentIndex = RANKS.indexOf(currentRank);
    const nextRank = RANKS[currentIndex + 1] || null;
    let progress = 100;
    let nextMin = null;
    if (nextRank) {
        const range = nextRank.min - currentRank.min;
        progress = range > 0 ? ((points - currentRank.min) / range) * 100 : 100;
        progress = Math.min(Math.max(progress, 0), 100);
        nextMin = nextRank.min;
    }
    return {
        ...currentRank,
        progress: progress,
        nextMin: nextMin,
        nextName: nextRank ? nextRank.name : 'مكتمل 🏆',
        image: currentRank.image,
        lockedImage: currentRank.lockedImage,
    };
}

